import { readFileSync } from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert';

const DIR = '/tmp/io-screening-27b-guardrail-safe-pTUiT1';
const html = readFileSync(DIR + '/index.html', 'utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
assert(m, 'script tag found');

const sandbox = { console };
vm.createContext(sandbox);
vm.runInContext(m[1], sandbox, { filename: 'inline-app.js' });
const app = sandbox.__app;
assert(app, 'app test hook exposed');

const rows = app.parseCSV(app.csv);
assert.strictEqual(rows.length, 8, 'parsed 8 data rows');
assert.deepStrictEqual(Object.keys(rows[0]),
  ['district','year','women_enrolled','completed_training','employed_at_6_months','source']);

/* Formula 1 & 2 spot checks */
const g22 = app.addMetrics(rows.find(r => r.district === 'Gaya' && r.year === 2022));
assert.ok(Math.abs(g22.completionRate - 80) < 1e-9, 'Gaya 2022 completion = 80.0%');
assert.ok(Math.abs(g22.employmentRate - 65) < 1e-9, 'Gaya 2022 employment = 65.0%');

const k23 = app.addMetrics(rows.find(r => r.district === 'Kishanganj' && r.year === 2023));
assert.ok(Math.abs(k23.completionRate - 68) < 1e-9, 'Kishanganj 2023 completion = 68.0%');
assert.ok(Math.abs(k23.employmentRate - 342 / 612 * 100) < 1e-9, 'Kishanganj 2023 employment = 55.9%');

/* overall totals (rates computed on summed counts, not averaged) */
const t22 = app.totalMetrics(rows.filter(r => r.year === 2022));
assert.strictEqual(t22.women_enrolled, 3900);
assert.strictEqual(t22.completed_training, 2925);
assert.strictEqual(t22.employed_at_6_months, 1844);
assert.ok(Math.abs(t22.completionRate - 75) < 1e-9, '2022 overall completion = 75.0%');
assert.ok(Math.abs(t22.employmentRate - 1844 / 2925 * 100) < 1e-9, '2022 overall employment = 63.0%');

const t23 = app.totalMetrics(rows.filter(r => r.year === 2023));
assert.strictEqual(t23.women_enrolled, 4300);
assert.strictEqual(t23.completed_training, 3333);
assert.strictEqual(t23.employed_at_6_months, 2206);
assert.ok(Math.abs(t23.completionRate - 3333 / 4300 * 100) < 1e-9, '2023 overall completion = 77.5%');
assert.ok(Math.abs(t23.employmentRate - 2206 / 3333 * 100) < 1e-9, '2023 overall employment = 66.2%');

/* zero-division safety */
assert.strictEqual(app.rate(5, 0), null);

/* embedded copy must match the real CSV */
const csvRows = app.parseCSV(readFileSync(DIR + '/women_livelihood_outcomes.csv', 'utf8'));
assert.deepStrictEqual(csvRows, rows, 'embedded CSV matches women_livelihood_outcomes.csv');

/* static content checks */
for (const needle of [
  'completed_training &divide; women_enrolled',
  'employed_at_6_months &divide; completed_training',
  'Data source', 'Methodology', 'baseYear', 'compareYear', 'id="swap"',
  'women_livelihood_outcomes.csv', 'Completion rate', 'Employment rate'
]) assert(html.includes(needle), 'HTML contains: ' + needle);
assert(!/__(CSS2|SECTIONS|JS_DATA|JS_RENDER1|JS_RENDER2|JS_INIT)__/.test(html), 'no leftover markers');

console.log('ALL TESTS PASSED');
console.log('2022 overall: completion ' + t22.completionRate.toFixed(1) + '% | employment ' + t22.employmentRate.toFixed(1) + '%');
console.log('2023 overall: completion ' + t23.completionRate.toFixed(1) + '% | employment ' + t23.employmentRate.toFixed(1) + '%');

/* controls */
.controls{display:flex;gap:16px;align-items:flex-end;flex-wrap:wrap}
.control label{display:block;font-size:13px;font-weight:600;color:var(--muted);margin-bottom:4px}
select{padding:8px 12px;font-size:15px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink);min-width:110px}
select:focus{outline:2px solid var(--rose);outline-offset:1px;border-color:var(--rose)}
#swap{margin-bottom:1px;padding:8px 14px;font-size:14px;font-weight:600;color:var(--rose);background:var(--rose-soft);border:1px solid var(--rose-line);border-radius:10px;cursor:pointer}
#swap:hover{background:#fbd5e3}
.hint{margin:0;flex-basis:100%;color:var(--muted);font-size:13px}
/* KPI cards */
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
.kpi{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px 18px;box-shadow:0 1px 2px rgba(36,26,32,.05)}
.kpi .t{font-size:13px;color:var(--muted);font-weight:600}
.kpi .v{font-size:26px;font-weight:700;margin:4px 0 8px}
.chip{display:inline-block;font-size:12.5px;font-weight:700;padding:2px 9px;border-radius:999px;white-space:nowrap}
.chip.up{color:var(--up);background:#ebf9ee}
.chip.down{color:var(--down);background:#fdecec}
.chip.flat{color:var(--muted);background:#f1ecef}
.vs{display:block;margin-top:6px;font-size:12px;color:var(--muted)}
/* table */
.tablewrap{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:14px;min-width:920px}
th,td{padding:9px 10px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}
th{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
th:first-child,td:first-child{text-align:left}
thead tr:first-child th{border-bottom:2px solid var(--rose-soft)}
thead tr.first .grp-base{color:var(--rose)}
thead tr.first .grp-comp{color:var(--teal)}
tr.total td{font-weight:700;border-top:2px solid var(--ink);border-bottom:none}
td.up{color:var(--up);font-weight:700}
td.down{color:var(--down);font-weight:700}
td.muted{color:var(--muted)}
/* chart */
.legend{display:flex;gap:18px;margin:0 0 14px;font-size:13.5px;color:var(--muted);flex-wrap:wrap}
.sw{display:inline-block;width:12px;height:12px;border-radius:3px;margin-right:6px;vertical-align:-1px}
.sw-comp{background:var(--rose)}
.sw-emp{background:var(--teal)}
.crow{display:grid;grid-template-columns:110px 1fr;gap:12px;align-items:center;padding:7px 0;border-bottom:1px dashed var(--line)}
.crow:last-child{border-bottom:none}
.clab{font-weight:600;font-size:14px}
.barline{display:flex;align-items:center;gap:8px}
.barline + .barline{margin-top:5px}
.bar{height:12px;border-radius:999px;min-width:2px}
.bar.comp{background:var(--rose)}
.bar.emp{background:var(--teal)}
.val{font-size:12.5px;color:var(--muted);font-weight:600}
/* methodology */
.formulas{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px}
.formula{border-radius:12px;padding:14px 16px}
.formula.f1{background:var(--rose-soft);border:1px solid var(--rose-line)}
.formula.f2{background:var(--teal-soft);border:1px solid var(--teal-line)}
.formula h3{margin:0 0 8px;font-size:14.5px}
.formula .eq{margin:0 0 8px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:13px;background:#fff;border:1px dashed #d8c5cf;padding:9px 11px;border-radius:8px}
.formula.f2 .eq{border-color:#a9dcc6}
.formula p:last-child{margin:0;font-size:13px;color:var(--muted)}
.worked{margin-top:16px;padding-top:16px;border-top:1px solid var(--line);display:flex;gap:24px;align-items:flex-start;flex-wrap:wrap}
.worked .inline{display:flex;align-items:center;gap:10px}
.worked .inline label{margin:0}
#exampleCalc{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:13.5px}
#exampleCalc p{margin:5px 0}
#exampleCalc .res{font-weight:700;color:var(--rose)}
/* source */
.source{font-size:13.5px;color:var(--muted)}
.source h3{margin:0 0 6px;font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:var(--ink)}
.source p{margin:0}
code{background:#f4edf1;padding:1px 6px;border-radius:6px;font-size:12.5px}
@media(max-width:640px){
  .crow{grid-template-columns:84px 1fr}
  .clab{font-size:12.5px}
}

