/* ---- data (fallback copy of women_livelihood_outcomes.csv) ---- */
const EMBEDDED_CSV = [
  'district,year,women_enrolled,completed_training,employed_at_6_months,source',
  'Gaya,2022,1000,800,520,synthetic women livelihood outcomes fixture',
  'Gaya,2023,1100,902,616,synthetic women livelihood outcomes fixture',
  'Nalanda,2022,900,765,540,synthetic women livelihood outcomes fixture',
  'Nalanda,2023,1000,870,650,synthetic women livelihood outcomes fixture',
  'Purnia,2022,1200,840,504,synthetic women livelihood outcomes fixture',
  'Purnia,2023,1300,949,598,synthetic women livelihood outcomes fixture',
  'Kishanganj,2022,800,520,280,synthetic women livelihood outcomes fixture',
  'Kishanganj,2023,900,612,342,synthetic women livelihood outcomes fixture'
].join('\n');

/* ---- pure helpers ---- */
function parseCSV(text){
  const lines = String(text).trim().split(/\r?\n/).filter(Boolean);
  if(!lines.length) return [];
  const head = lines[0].split(',').map(s => s.trim());
  return lines.slice(1).map(line => {
    const parts = line.split(',').map(s => s.trim());
    const row = {};
    head.forEach((h, i) => { row[h] = parts[i]; });
    row.year = +row.year;
    row.women_enrolled = +row.women_enrolled;
    row.completed_training = +row.completed_training;
    row.employed_at_6_months = +row.employed_at_6_months;
    return row;
  });
}

/* Formula 1: completion rate = completed / enrolled * 100 */
/* Formula 2: employment rate  = employed_at_6mo / completed * 100 */
function rate(num, den){ return den > 0 ? (num / den) * 100 : null; }

function addMetrics(r){
  return Object.assign({}, r, {
    completionRate: rate(r.completed_training, r.women_enrolled),
    employmentRate: rate(r.employed_at_6_months, r.completed_training)
  });
}

function totalMetrics(rows){
  const e = rows.reduce((a, r) => a + r.women_enrolled, 0);
  const c = rows.reduce((a, r) => a + r.completed_training, 0);
  const m = rows.reduce((a, r) => a + r.employed_at_6_months, 0);
  return { women_enrolled: e, completed_training: c, employed_at_6_months: m,
           completionRate: rate(c, e), employmentRate: rate(m, c) };
}

const esc = s => String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmtInt = n => (n == null || isNaN(n)) ? '\u2013' : n.toLocaleString('en-IN');
const fmtPct = p => (p == null || isNaN(p)) ? '\u2013' : p.toFixed(1) + '%';

/* ---- state ---- */
let rows = parseCSV(EMBEDDED_CSV);
let sourceNote = 'using the copy embedded in this page';
const CSV_FILE = 'women_livelihood_outcomes.csv';

function districtsOf(){
  const seen = [];
  rows.forEach(r => { if(!seen.includes(r.district)) seen.push(r.district); });
  return seen;
}
function yearsOf(){ return [...new Set(rows.map(r => r.year))].sort((a, b) => a - b); }
function rowFor(district, year){
  const r = rows.find(x => x.district === district && x.year === year);
  return r ? addMetrics(r) : null;
}

