/* ---- rendering (browser only) ---- */
function chip(delta, unit){
  if(delta == null || isNaN(delta)) return '<span class="chip flat">n/a</span>';
  if(Math.abs(delta) < 1e-9) return '<span class="chip flat">no change</span>';
  const cls = delta > 0 ? 'up' : 'down';
  const arrow = delta > 0 ? '\u25B2' : '\u25BC';
  return `<span class="chip ${cls}">${arrow} ${Math.abs(delta).toFixed(1)}${unit}</span>`;
}

function kpi(title, value, chipHtml, vsText){
  return `<div class="kpi"><div class="t">${title}</div><div class="v">${value}</div>${chipHtml}<span class="vs">${vsText}</span></div>`;
}

function renderKpis(bt, ct, base, compare){
  const rateDelta = (c, b) => (c == null || b == null) ? null : c - b;
  const countChip = (cur, prev) => {
    if(cur == null || prev == null) return '<span class="chip flat">n/a</span>';
    const d = cur - prev;
    if(d === 0) return '<span class="chip flat">no change</span>';
    const rel = prev !== 0 ? (d / prev) * 100 : null;
    const cls = d > 0 ? 'up' : 'down';
    const arrow = d > 0 ? '\u25B2' : '\u25BC';
    return `<span class="chip ${cls}">${arrow} ${d > 0 ? '+' : ''}${fmtInt(d)}${rel == null ? '' : ' (' + (rel > 0 ? '+' : '') + rel.toFixed(1) + '%)'}</span>`;
  };
  document.getElementById('kpis').innerHTML =
    kpi(`Completion rate \u00B7 ${compare}`, fmtPct(ct.completionRate),
        chip(rateDelta(ct.completionRate, bt.completionRate), ' pp'), `vs ${base}: ${fmtPct(bt.completionRate)}`) +
    kpi(`Employment rate at 6 months \u00B7 ${compare}`, fmtPct(ct.employmentRate),
        chip(rateDelta(ct.employmentRate, bt.employmentRate), ' pp'), `vs ${base}: ${fmtPct(bt.employmentRate)}`) +
    kpi(`Women enrolled \u00B7 ${compare}`, fmtInt(ct.women_enrolled),
        countChip(ct.women_enrolled, bt.women_enrolled), `vs ${base}: ${fmtInt(bt.women_enrolled)}`) +
    kpi(`Employed at 6 months \u00B7 ${compare}`, fmtInt(ct.employed_at_6_months),
        countChip(ct.employed_at_6_months, bt.employed_at_6_months), `vs ${base}: ${fmtInt(bt.employed_at_6_months)}`);
}

function rowCells(r){
  if(!r) return '<td class="muted">\u2013</td>'.repeat(5);
  return `<td>${fmtInt(r.women_enrolled)}</td><td>${fmtInt(r.completed_training)}</td>` +
         `<td>${fmtInt(r.employed_at_6_months)}</td><td>${fmtPct(r.completionRate)}</td><td>${fmtPct(r.employmentRate)}</td>`;
}

function cellDelta(a, b){
  if(a == null || b == null) return '<td class="muted">\u2013</td>';
  const d = a - b;
  if(Math.abs(d) < 1e-9) return '<td>0.0 pp</td>';
  const cls = d > 0 ? 'up' : 'down';
  const arrow = d > 0 ? '\u25B2 ' : '\u25BC ';
  return `<td class="${cls}">${arrow}${d > 0 ? '+' : ''}${d.toFixed(1)} pp</td>`;
}

function renderTable(districts, base, compare){
  document.getElementById('tableCaption').textContent = `${base} vs ${compare}`;
  const head =
    `<thead>` +
    `<tr class="first"><th rowspan="2">District</th>` +
    `<th colspan="5" class="grp-base">${base} (base)</th>` +
    `<th colspan="5" class="grp-comp">${compare} (compare)</th>` +
    `<th colspan="2">${base} \u2192 ${compare}</th></tr>` +
    `<tr><th>Enrolled</th><th>Completed</th><th>Employed (6 mo)</th><th>Completion rate</th><th>Employment rate</th>` +
    `<th>Enrolled</th><th>Completed</th><th>Employed (6 mo)</th><th>Completion rate</th><th>Employment rate</th>` +
    `<th>Completion \u0394</th><th>Employment \u0394</th></tr>` +
    `</thead><tbody>`;
  let body = '';
  districts.forEach(d => {
    const a = rowFor(d, base);
    const b = rowFor(d, compare);
    body += `<tr><td>${esc(d)}</td>${rowCells(a)}${rowCells(b)}` +
            cellDelta(b && a ? b.completionRate : null, a ? a.completionRate : null) +
            cellDelta(b && a ? b.employmentRate : null, a ? a.employmentRate : null) +
            `</tr>`;
  });
  const bt = totalMetrics(rows.filter(r => r.year === base));
  const ct = totalMetrics(rows.filter(r => r.year === compare));
  body += `<tr class="total"><td>All districts</td>${rowCells(bt)}${rowCells(ct)}` +
          cellDelta(ct.completionRate, bt.completionRate) +
          cellDelta(ct.employmentRate, bt.employmentRate) +
          `</tr>`;
  document.getElementById('dataTable').innerHTML = head + body + '</tbody>';
}

