      `</div></div>`;
  });
  document.getElementById('chart').innerHTML = h;
}

function renderExample(base){
  const sel = document.getElementById('exampleDistrict');
  const d = sel.value;
  const r = rowFor(d, base);
  const el = document.getElementById('exampleCalc');
  if(!r){ el.innerHTML = ''; return; }
  el.innerHTML =
    `<p><strong>${esc(d)} \u00B7 ${base}</strong></p>` +
    `<p>Completion rate = ${fmtInt(r.completed_training)} \u00F7 ${fmtInt(r.women_enrolled)} \u00D7 100 = <span class="res">${fmtPct(r.completionRate)}</span></p>` +
