function populateSelects(){
  const years = yearsOf();
  const districts = districtsOf();
  const baseSel = document.getElementById('baseYear');
  const compareSel = document.getElementById('compareYear');
  const exSel = document.getElementById('exampleDistrict');
  baseSel.innerHTML = years.map(y => `<option value="${y}">${y}</option>`).join('');
  compareSel.innerHTML = years.map(y => `<option value="${y}">${y}</option>`).join('');
  baseSel.value = String(years[0]);
  compareSel.value = String(years[years.length - 1]);
  exSel.innerHTML = districts.map(d => `<option value="${esc(d)}">${esc(d)}</option>`).join('');
}

function init(){
  const baseSel = document.getElementById('baseYear');
  const compareSel = document.getElementById('compareYear');
  const exSel = document.getElementById('exampleDistrict');
  baseSel.addEventListener('change', render);
  compareSel.addEventListener('change', render);
  exSel.addEventListener('change', render);
  document.getElementById('swap').addEventListener('click', () => {
    const t = baseSel.value; baseSel.value = compareSel.value; compareSel.value = t;
    render();
  });
  populateSelects();
  render();
  /* if served over HTTP, prefer the live CSV so updated data shows automatically */
  fetch(CSV_FILE, { cache: 'no-store' })
    .then(res => res.ok ? res.text() : null)
    .then(txt => {
      if(!txt) return;
      const r2 = parseCSV(txt);
      if(!r2.length) return;
      rows = r2;
      sourceNote = 'loaded live from <code>' + esc(CSV_FILE) + '</code>';
      const b = baseSel.value, c = compareSel.value;
      populateSelects();
      if(yearsOf().includes(+b)) baseSel.value = b;
      if(yearsOf().includes(+c)) compareSel.value = c;
      render();
    })
    .catch(() => { /* file:// or offline — embedded copy already shown */ });
}

if(typeof document !== 'undefined' && document.getElementById){
  init();
}

/* test hook (used by the verification script, harmless in browsers) */
globalThis.__app = { parseCSV, rate, addMetrics, totalMetrics, csv: EMBEDDED_CSV };

